<script setup>
import { computed, onMounted, ref } from 'vue';
import { BookOpen, Plus, RefreshCw, Clock3, CircleCheck, CircleX, Pencil, Send, X, ChevronLeft, ChevronRight, Eye, Trash2 } from 'lucide-vue-next';
import { useAuthStore } from '~/stores/api/auth';
import { useTutorQuestionsStore } from '~/stores/api/tutorQuestions';
import { canAccessPage } from '~/utils/roles';
import QuestionForm from '~/components/question-bank/QuestionForm.vue';

definePageMeta({ layout: 'default' });
const auth=useAuthStore(); const store=useTutorQuestionsStore();
const ready=ref(false); const formOpen=ref(false); const editing=ref(null); const detail=ref(null); const actionError=ref(''); const notice=ref('');
const counts=computed(() => store.summary);
const statusText={draft:'Draft',review:'Menunggu Review',active:'Aktif',rejected:'Ditolak'};
const statusTone={draft:'bg-surface-container text-outline',review:'bg-soft-orange text-on-secondary-container',active:'bg-success-soft text-success-emerald',rejected:'bg-danger-soft text-danger-rose'};
const difficulty={easy:'Mudah',medium:'Sedang',hard:'Sulit'};
function date(value){return value?new Date(value).toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'short'}):'—';}
function openCreate(){editing.value=null;formOpen.value=true;actionError.value='';}
function openEdit(item){editing.value=item;formOpen.value=true;actionError.value='';}
async function save(payload){actionError.value='';notice.value='';try{const response=await store.save(editing.value?.id,payload);notice.value=response.message;formOpen.value=false;await Promise.all([store.fetchItems(),store.fetchSummary()]);}catch(error){actionError.value=error?.data?.message||'Gagal menyimpan soal.';}}
async function submitAgain(item){actionError.value='';notice.value='';try{const response=await store.submit(item.id);notice.value=response.message;await Promise.all([store.fetchItems(),store.fetchSummary()]);if(detail.value?.id===item.id)detail.value=response.data;}catch(error){actionError.value=error?.data?.message||'Gagal mengirim ulang soal.';}}
async function remove(item){if(!confirm('Hapus soal ini?'))return;actionError.value='';try{await store.remove(item.id);notice.value='Soal berhasil dihapus.';await Promise.all([store.fetchItems(),store.fetchSummary()]);}catch(error){actionError.value=error?.data?.message||'Gagal menghapus soal.';}}
onMounted(async()=>{auth.initializeAuth();if(!auth.token)return navigateTo('/login');const user=await auth.fetchCurrentUser();if(Number(user?.role)!==3||!canAccessPage(user?.role,'question.own'))return navigateTo('/dashboard');ready.value=true;await Promise.all([store.fetchItems(),store.fetchSummary()]);});
</script>
<template>
  <div class="mx-auto w-full max-w-[1450px] min-w-0 px-4 py-5 sm:px-6 sm:py-7 lg:px-8"><template v-if="ready && Number(auth.user?.role)===3"><header class="mb-5 flex flex-wrap items-start justify-between gap-4"><div><h1 class="font-headline-md text-headline-md text-on-surface">Bank Soal Tutor</h1><p class="mt-1 font-body-sm text-body-sm text-on-surface-variant">Buat soal, lihat status review, dan perbaiki soal yang ditolak Admin.</p></div><button class="inline-flex items-center gap-2 rounded-2xl bg-primary-container px-4 py-2.5 text-sm text-white" @click="openCreate"><Plus class="h-4 w-4" />Buat Soal</button></header>
    <p v-if="notice" role="status" class="mb-4 rounded-2xl bg-success-soft p-3 text-success-emerald">{{ notice }}</p><p v-if="actionError && !formOpen" role="alert" class="mb-4 rounded-2xl bg-danger-soft p-3 text-danger-rose">{{ actionError }}</p>
    <section class="mb-5 grid grid-cols-2 gap-3 md:grid-cols-4"><article v-for="item in [{label:'Total Soal',value:store.pagination.total,icon:BookOpen,tone:'bg-pale-blue text-primary-container'},{label:'Menunggu Review',value:counts.review,icon:Clock3,tone:'bg-soft-orange text-on-secondary-container'},{label:'Aktif',value:counts.active,icon:CircleCheck,tone:'bg-success-soft text-success-emerald'},{label:'Ditolak',value:counts.rejected,icon:CircleX,tone:'bg-danger-soft text-danger-rose'}]" :key="item.label" class="rounded-3xl border border-soft-blue bg-surface-white p-4 shadow-sm"><div class="mb-3 flex h-10 w-10 items-center justify-center rounded-2xl" :class="item.tone"><component :is="item.icon" class="h-5 w-5" /></div><p class="text-xs text-outline">{{ item.label }}</p><strong class="font-title-md text-title-md">{{ item.value }}</strong></article></section>
    <section class="rounded-3xl border border-soft-blue bg-surface-white p-4 shadow-sm sm:p-6"><div class="mb-4 flex items-center justify-between"><h2 class="font-title-md text-title-md">Soal Saya</h2><button class="inline-flex items-center gap-2 text-sm text-primary-container" @click="store.fetchItems()"><RefreshCw class="h-4 w-4" />Muat Ulang</button></div><div v-if="store.error" role="alert" class="rounded-2xl bg-danger-soft p-4 text-danger-rose">{{ store.error }}</div><div v-else-if="store.loading" class="space-y-3"><div v-for="i in 4" :key="i" class="h-28 animate-pulse rounded-2xl bg-surface-container" /></div><div v-else-if="!store.items.length" class="py-12 text-center"><BookOpen class="mx-auto mb-3 h-10 w-10 text-primary-container" /><h3 class="font-title-md text-title-md">Belum ada soal</h3><p class="mt-1 text-on-surface-variant">Buat soal pertama untuk dikirim ke Admin.</p></div><div v-else class="space-y-3"><article v-for="item in store.items" :key="item.id" class="rounded-2xl border border-soft-blue p-4"><div class="flex flex-wrap gap-2 text-xs"><span class="rounded-full bg-pale-blue px-2.5 py-1 text-primary-container">{{ item.subtest }}</span><span class="rounded-full bg-surface-container px-2.5 py-1">{{ item.category }}</span><span class="rounded-full bg-surface-container px-2.5 py-1">{{ difficulty[item.difficulty] }}</span><span class="ml-auto rounded-full px-2.5 py-1" :class="statusTone[item.status]">{{ statusText[item.status] }}</span></div><p class="mt-3 line-clamp-3 font-label-md text-label-md">{{ item.question }}</p><p class="mt-2 text-xs text-outline">{{ item.status==='review'?'Diajukan':'Dibuat' }} {{ date(item.submitted_at||item.created_at) }}</p><p v-if="item.status==='rejected' && item.rejection_reason" class="mt-3 rounded-xl bg-danger-soft p-3 text-sm text-danger-rose"><strong>Alasan Admin:</strong> {{ item.rejection_reason }}</p><div class="mt-4 flex flex-wrap justify-end gap-2"><button class="inline-flex items-center gap-1 rounded-xl border border-soft-blue px-3 py-2 text-sm" @click="detail=item"><Eye class="h-4 w-4" />Detail</button><button v-if="['draft','rejected'].includes(item.status)" class="inline-flex items-center gap-1 rounded-xl border border-soft-blue px-3 py-2 text-sm" @click="openEdit(item)"><Pencil class="h-4 w-4" />Edit</button><button v-if="['rejected','draft'].includes(item.status)" :disabled="store.saving" class="inline-flex items-center gap-1 rounded-xl bg-primary-container px-3 py-2 text-sm text-white disabled:opacity-50" @click="submitAgain(item)"><Send class="h-4 w-4" />Kirim Ulang</button><button v-if="['draft','rejected'].includes(item.status)" class="inline-flex items-center gap-1 rounded-xl border border-danger-rose px-3 py-2 text-sm text-danger-rose" @click="remove(item)"><Trash2 class="h-4 w-4"/>Hapus</button></div></article></div><div class="mt-5 flex items-center justify-end gap-3 text-sm"><span>Halaman {{ store.pagination.page }} / {{ store.pagination.total_pages }}</span><button :disabled="store.pagination.page<=1" class="rounded-xl border border-soft-blue p-2 disabled:opacity-40" aria-label="Halaman sebelumnya" @click="store.pagination.page--;store.fetchItems()"><ChevronLeft class="h-4 w-4" /></button><button :disabled="store.pagination.page>=store.pagination.total_pages" class="rounded-xl border border-soft-blue p-2 disabled:opacity-40" aria-label="Halaman berikutnya" @click="store.pagination.page++;store.fetchItems()"><ChevronRight class="h-4 w-4" /></button></div></section>
    <div v-if="formOpen" class="fixed inset-0 z-50 overflow-y-auto bg-black/50 p-3 sm:p-6" @click.self="formOpen=false"><div class="mx-auto my-4 w-full max-w-3xl"><div class="mb-3 flex justify-between rounded-2xl bg-surface-white p-4"><h2 class="font-title-md text-title-md">{{ editing?'Edit Soal':'Buat Soal' }}</h2><button aria-label="Tutup formulir" @click="formOpen=false"><X class="h-5 w-5" /></button></div><p v-if="editing?.status==='rejected'" class="mb-3 rounded-2xl bg-danger-soft p-3 text-sm text-danger-rose">Alasan Admin: {{ editing.rejection_reason }}. Simpan perbaikan, lalu klik Kirim Ulang.</p><p v-if="actionError" role="alert" class="mb-3 rounded-2xl bg-danger-soft p-3 text-danger-rose">{{ actionError }}</p><QuestionForm :key="editing?.id||'new'" tutor :initial="editing" :saving="store.saving" @submit="save" /></div></div>
    <div v-if="detail" class="fixed inset-0 z-50 flex justify-end bg-black/40" @click.self="detail=null"><div role="dialog" aria-modal="true" aria-label="Detail soal Tutor" class="h-full w-full max-w-xl overflow-y-auto bg-surface-white p-5 shadow-2xl"><div class="mb-5 flex justify-between"><h2 class="font-title-md text-title-md">Detail Soal</h2><button aria-label="Tutup detail" @click="detail=null"><X class="h-5 w-5" /></button></div><p class="mb-3 text-xs text-outline">{{ detail.subtest }} · {{ detail.category }} · {{ difficulty[detail.difficulty] }} · {{ statusText[detail.status] }}</p><p class="mb-5 whitespace-pre-wrap font-label-md text-label-md">{{ detail.question }}</p><div v-for="option in detail.options||[]" :key="option.key" class="mb-2 rounded-xl border border-soft-blue p-3" :class="option.key===detail.correct_answer?'bg-success-soft':''"><strong class="mr-2">{{ option.key }}</strong>{{ option.text }}<span v-if="option.key===detail.correct_answer" class="ml-2 text-xs text-success-emerald">✓ Jawaban benar</span></div><h3 class="mt-5 font-label-sm text-label-sm">Pembahasan</h3><p class="mt-2 whitespace-pre-wrap rounded-xl bg-surface-container-low p-3">{{ detail.explanation }}</p><p v-if="detail.rejection_reason" class="mt-4 rounded-xl bg-danger-soft p-3 text-danger-rose">Alasan Admin: {{ detail.rejection_reason }}</p></div></div>
  </template><div v-else class="h-40 animate-pulse rounded-3xl bg-surface-container" aria-label="Memuat soal Tutor" /></div>
</template>
